<template><q-page class="review-page"><div class="row items-center justify-between q-mb-md"><div><p class="eyebrow">REVISÃO</p><h1>Pratique sua lembrança</h1></div><q-btn flat no-caps label="Revisão rápida" @click="load('quick')"/></div><q-banner v-if="error" rounded class="error q-mb-md">{{ error }}</q-banner><q-card v-if="currentCard" class="review-card"><q-card-section><q-linear-progress rounded color="primary" :value="index / Math.max(1, session?.cards.length ?? 1)"/><p class="q-mt-md">Card {{ index + 1 }} de {{ session?.cards.length }}</p><h2>{{ revealed ? currentCard.back : currentCard.front }}</h2><q-btn v-if="!revealed" unelevated no-caps color="primary" label="Revelar resposta" @click="revealed=true"/><div v-else class="rating"><q-btn v-for="item in ratings" :key="item.value" no-caps :color="item.color" :label="item.label" :loading="loading" @click="submit(item.value)"/></div></q-card-section></q-card><q-card v-else-if="!loading" class="review-card"><q-card-section class="empty">Não há cards vencidos para revisar agora.</q-card-section></q-card></q-page></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { useReview } from './useReview';const { error,loading,loadSession,rate,session }=useReview();const index=ref(0),revealed=ref(false);const currentCard=computed(()=>session.value?.cards[index.value]??null);const ratings=[{value:'AGAIN',label:'Não lembrei',color:'negative'},{value:'HARD',label:'Difícil',color:'orange'},{value:'GOOD',label:'Lembrei',color:'primary'},{value:'EASY',label:'Fácil',color:'positive'}] as const;async function load(kind:'daily'|'quick'='daily'){await loadSession(kind);index.value=0;revealed.value=false};async function submit(value:typeof ratings[number]['value']){if(!session.value||!currentCard.value)return;if(await rate(session.value.id,currentCard.value.id,value)){index.value++;revealed.value=false}};onMounted(()=>void load());</script>
<style scoped>.review-page{max-width:820px;margin:auto;padding:40px 32px}.eyebrow{margin:0;color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.review-page h1,.review-page h2{color:#142950}.review-card{border-radius:22px;min-height:280px}.card-id{padding:28px 0;color:#627ca5;word-break:break-all}.rating{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.empty{color:#71819e;text-align:center;padding:54px}.error{background:#fff3f2;color:#ae2f25}@media(max-width:599px){.review-page{padding:24px 16px}.rating{grid-template-columns:1fr 1fr}}</style>
